"use client";
import { useState, useEffect, useRef, useCallback } from "react";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Avatar, AvatarFallback, AvatarImage } from "@/components/ui/avatar";
import { Tabs, TabsList, TabsTrigger } from "@/components/ui/tabs";
import { Send, Loader2, MessageCircle } from "lucide-react";
import { useGetUserQuery } from "@/app/provider/api/userApi";
import { toast } from "sonner";
import { cn } from "@/lib/utils";
import { formatDistanceToNow } from "date-fns";
import Cookies from "js-cookie";
import { useSocket } from "@/hooks/useSocket";
import { errorHandler } from "@/utils/errorHandler";
import { useRouter } from "next/navigation";
import { useRequireAuth } from "@/hooks/useRequireAuth";

type Section = "pre-event" | "during" | "post-event";

// Map UI section keys to the backend enum values
const SECTION_KEY: Record<Section, string> = {
  "pre-event": "PRE_EVENT",
  during: "DURING_EVENT",
  "post-event": "POST_EVENT",
};

interface ChatMessage {
  id: string;
  body?: string;
  content?: string;
  text?: string;
  sender?: {
    id?: string;
    displayName?: string;
    username?: string;
    avatarUrl?: string;
    role?: string;
  };
  senderId?: string;
  createdAt?: string;
  isOrganizer?: boolean;
}

interface EventChatTabProps {
  eventId: string;
}

const API_BASE = (process.env.NEXT_PUBLIC_API_URL ?? "")
  .trim()
  .replace(/\/$/, "");

function formatTime(dateStr?: string) {
  if (!dateStr) return "";
  try {
    return formatDistanceToNow(new Date(dateStr), { addSuffix: true });
  } catch {
    return "";
  }
}

function msgText(msg: ChatMessage) {
  return msg.body ?? msg.content ?? msg.text ?? "";
}

export function EventChatTab({ eventId }: EventChatTabProps) {
  const router = useRouter()
  const requireAuth = useRequireAuth();
  const [activeSection, setActiveSection] = useState<Section>("pre-event");
  const [message, setMessage] = useState("");
  const [messages, setMessages] = useState<ChatMessage[]>([]);
  const [isLoadingHistory, setIsLoadingHistory] = useState(false);

  // Maps optimistic message body → temp id so we can replace it when the
  // server echoes the real message back (prevents double-bubble).
  const pendingOptimisticRef = useRef<Map<string, string>>(new Map());

  const token = Cookies.get("accessToken");
  const isLoggedIn = !!token;
  const { data: meData } = useGetUserQuery(undefined, { skip: !isLoggedIn });
  const myId = meData?.data?.id;

  const { socketRef, isConnected } = useSocket("messaging", {
    enabled: !!eventId && !!token,
  });

  // Join room and listen for new messages.
  // Uses socket "connect" event directly so join:event-chat is re-emitted on every
  // (re)connect without depending on React state timing.
  useEffect(() => {
    const socket = socketRef.current;
    if (!socket) return;

    const section = SECTION_KEY[activeSection];

    const joinRoom = () => {
      console.log(
        `[event-chat] 🔗 join:event-chat  event=${eventId}  section=${section}  socketId=${
          socket.id ?? "pending"
        }`
      );
      socket.emit("join:event-chat", { eventId, section });
    };

    const handleNewMessage = (msg: ChatMessage) => {
      setMessages((prev) => {
        // Exact duplicate guard (server may echo to the sender too)
        if (msg.id && prev.some((m) => m.id === msg.id)) return prev;

        // If this is an echo of our own optimistic bubble, replace it with the
        // real message (correct id + server timestamp) instead of prepending a copy.
        const isOwn = msg.sender?.id === myId || msg.senderId === myId;
        if (isOwn) {
          const text = msgText(msg);
          const optId = pendingOptimisticRef.current.get(text);
          if (optId) {
            pendingOptimisticRef.current.delete(text);
            return prev.map((m) => (m.id === optId ? msg : m));
          }
        }

        // Prepend — newest message goes to the top, matching server order
        return [msg, ...prev];
      });
    };

    // Re-join on every (re)connect
    socket.on("connect", joinRoom);
    socket.on("new:event-chat", handleNewMessage);

    // If already connected when the effect runs, join immediately
    if (socket.connected) {
      console.log(`[event-chat] already connected — joining immediately`);
      joinRoom();
    } else {
      console.log(
        `[event-chat] not yet connected — will join when "connect" fires`
      );
    }

    return () => {
      socket.off("connect", joinRoom);
      socket.off("new:event-chat", handleNewMessage);
    };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [eventId, activeSection, socketRef]);

  const fetchHistory = useCallback(
    async (section: Section) => {
      if (!eventId) return;
      setIsLoadingHistory(true);
      try {
        const headers: HeadersInit = {};
        if (token) headers["Authorization"] = `Bearer ${token}`;

        const res = await fetch(
          `${API_BASE}/v1/events/${eventId}/chat/${SECTION_KEY[section]}`,
          { headers }
        );

        if (!res.ok) {
          const errorData = await res.json().catch(() => null);
          toast.error(errorData?.error?.message);
          setMessages([]);
          return;
        }

        const json = await res.json();
        // Server returns newest-first — keep that order as-is.
        const history: ChatMessage[] = json?.data?.data ?? [];
        setMessages(history);
      } catch (err) {
        toast.error(errorHandler(err));
        setMessages([]);
      } finally {
        setIsLoadingHistory(false);
      }
    },
    [eventId, token]
  );

  useEffect(() => {
    setMessages([]);
    pendingOptimisticRef.current.clear(); // discard any pending optimistics from old section
    fetchHistory(activeSection);
  }, [activeSection, fetchHistory]);

  // No auto-scroll needed — newest messages appear at the top naturally.

  const handleSend = () => {
    const text = message.trim();
    if (!text || !isConnected) return;
    if (!requireAuth({ tab: "chat" })) return;

    const socket = socketRef.current;
    socket?.emit("send:event-chat", {
      eventId,
      section: SECTION_KEY[activeSection],
      body: text,
    });

    // Add an optimistic bubble immediately so the sender sees their message
    // right away. When the server echoes it back via new:event-chat the
    // handleNewMessage handler will replace this with the real message.
    const optimisticId = `opt-${Date.now()}`;
    pendingOptimisticRef.current.set(text, optimisticId);
    const me = meData?.data as any;
    const optimistic: ChatMessage = {
      id: optimisticId,
      body: text,
      senderId: myId,
      sender: {
        id: myId,
        displayName: me?.displayName,
        username: me?.username,
        avatarUrl: me?.avatarUrl,
      },
      createdAt: new Date().toISOString(),
    };
    setMessages((prev) => [optimistic, ...prev]);
    setMessage("");
  };

  const handleKeyDown = (e: React.KeyboardEvent) => {
    if (e.key === "Enter" && !e.shiftKey) {
      e.preventDefault();
      handleSend();
    }
  };

  return (
    <div className="flex flex-col h-[calc(100vh-300px)] animate-fade-in">
      <div className="flex items-center gap-2 mb-4">
        <Tabs
          value={activeSection}
          onValueChange={(v) => setActiveSection(v as Section)}
          className="flex-1"
        >
          <TabsList className="w-full grid grid-cols-3 h-9">
            <TabsTrigger value="pre-event" className="text-xs">
              Pre-Event
            </TabsTrigger>
            <TabsTrigger value="during" className="text-xs">
              During
            </TabsTrigger>
            <TabsTrigger value="post-event" className="text-xs">
              Post-Event
            </TabsTrigger>
          </TabsList>
        </Tabs>
      </div>

      <div className="flex-1 overflow-y-auto space-y-4 mb-4 pr-1">
        {isLoadingHistory ? (
          <div className="flex items-center justify-center h-full">
            <Loader2 className="h-6 w-6 animate-spin text-primary" />
          </div>
        ) : messages.length === 0 ? (
          <div className="flex flex-col items-center justify-center h-full text-center py-12">
            <div className="h-16 w-16 rounded-full bg-muted flex items-center justify-center mb-3">
              <MessageCircle className="h-8 w-8 text-muted-foreground" />
            </div>
            <p className="font-medium text-foreground">No messages yet</p>
            <p className="text-sm text-muted-foreground">
              Be the first to start the conversation!
            </p>
          </div>
        ) : (
          messages?.map((msg, i) => {
            const isMe = msg.sender?.id === myId || msg.senderId === myId;
            const senderName =
              msg.sender?.displayName ?? msg.sender?.username ?? "User";
            const senderId = msg.sender?.id;
            const avatarUrl = msg.sender?.avatarUrl ?? "";
            const isOrganizer =
              msg.sender?.role === "ORGANIZER" || msg.isOrganizer;
            const timestamp = formatTime(msg.createdAt);

            return (
              <div
                key={msg.id ?? i}
                className={cn("flex gap-3", isMe && "flex-row-reverse")}
              >
                {!isMe && (
                  <Avatar className="h-8 w-8 shrink-0">
                    <AvatarImage src={avatarUrl} />
                    <AvatarFallback>{senderName.charAt(0)}</AvatarFallback>
                  </Avatar>
                )}

                <div
                  className={cn(
                    "flex flex-col max-w-[75%]",
                    isMe && "items-end"
                  )}
                >
                  {!isMe && (
                    <div className="flex items-center gap-2 mb-1">
                      <span className="font-semibold text-xs text-foreground" onClick={() => senderId && router.push(`/users/${senderId}`)}>
                        {senderName}
                      </span>
                      {isOrganizer && (
                        <span className="text-[10px] font-medium text-primary bg-primary/10 px-1.5 py-0.5 rounded-full">
                          Organizer
                        </span>
                      )}
                      {timestamp && (
                        <span className="text-[10px] text-muted-foreground">
                          {timestamp}
                        </span>
                      )}
                    </div>
                  )}

                  <div
                    className={cn(
                      "rounded-2xl px-3 py-2 text-sm wrap-break-word",
                      isMe
                        ? "bg-[#531342] text-white rounded-tr-sm"
                        : "bg-muted text-foreground rounded-tl-sm"
                    )}
                  >
                    {msgText(msg)}
                  </div>

                  {isMe && timestamp && (
                    <span className="text-[10px] text-muted-foreground mt-1">
                      {timestamp}
                    </span>
                  )}
                </div>
              </div>
            );
          })
        )}
      </div>

      <div className="flex items-center gap-2 p-3 rounded-2xl border border-border bg-background">
        {isLoggedIn ? (
          <>
            <Input
              placeholder={isConnected ? "Type a message..." : "Connecting..."}
              value={message}
              onChange={(e) => setMessage(e.target.value)}
              onKeyDown={handleKeyDown}
              className="flex-1 border-0 bg-transparent focus-visible:ring-0 px-0"
              disabled={!isConnected}
            />
            <Button
              size="icon"
              className="rounded-full shrink-0 bg-[#531342] hover:bg-[#531342]/90"
              disabled={!message.trim() || !isConnected}
              onClick={handleSend}
            >
              <Send className="h-4 w-4" />
            </Button>
          </>
        ) : (
          <button
            onClick={() => requireAuth({ tab: "chat" })}
            className="flex-1 text-center text-sm text-muted-foreground hover:text-foreground transition-colors py-1"
          >
            Sign in to join the conversation
          </button>
        )}
      </div>
    </div>
  );
}
